from account_access_models import AccountAccessResult
from account_access_policy import AccountAccessPolicy
from account_access_repository import AccountAccessRepository

class AccountAccessService:
    def __init__(self, repository: AccountAccessRepository, policy: AccountAccessPolicy, audit=None, adapter=None, clock=None):
        self.repository = repository
        self.policy = policy
        self.audit = audit
        self.adapter = adapter
        self.clock = clock

    def acquire_account_access(self, record_id: str, owner: str) -> dict[str, object]:
        record = self.repository.get(record_id)
        token = self.repository.next_token()
        record.owner = owner
        record.token = token
        record.status = "acquired"
        if self.audit:
            self.audit.record("acquired", record_id=record_id, owner=owner, token=token)
        return {"ok": True, "record_id": record_id, "owner": owner, "token": token}

    def apply_account_access(self, record_id: str, owner: str, token: int, value: int, metadata: dict[str, object] | None = None) -> dict[str, object]:
        reasons = self.policy.evaluate(value, metadata)
        status = self.policy.status_for(reasons)
        if self.policy.should_call_adapter(status) and self.adapter:
            self.adapter.send({"record_id": record_id, "owner": owner, "value": value})
        self.repository.guarded_save(record_id, owner, token, value, status)
        if self.audit:
            self.audit.record(status, record_id=record_id, owner=owner, token=token, reasons=list(reasons))
        return AccountAccessResult(status == "approved", record_id, status, tuple(reasons)).to_dict()

    def summarize_account_access(self) -> dict[str, object]:
        rows = [record.to_dict() for record in self.repository.list_records()]
        return {"count": len(rows), "rows": rows}

