from account_access_models import AccountAccessRecord
from account_access_repository import AccountAccessRepository
from account_access_policy import AccountAccessPolicy
from account_access_service import AccountAccessService
from account_access_adapter import ExternalAdapter

def setup_service():
    repo=AccountAccessRepository([AccountAccessRecord("r1", "none"), AccountAccessRecord("r2", "none")])
    audit=AuditTrail() if "AuditTrail" in globals() else None
    adapter=ExternalAdapter() if "ExternalAdapter" in globals() else None
    clock=ManualClock(0) if "ManualClock" in globals() else None
    return repo, audit, adapter, AccountAccessService(repo, AccountAccessPolicy(limit=100), audit, adapter, clock)

def test_first_acquire_returns_token():
    _,_,_,s=setup_service(); assert s.acquire_account_access("r1","w1")["token"] == 1

def test_second_acquire_returns_newer_token():
    _,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); b=s.acquire_account_access("r1","w2"); assert b["token"] > a["token"]

def test_stale_token_is_rejected():
    repo,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); s.acquire_account_access("r1","w2"); assert s.apply_account_access("r1","w1",a["token"],10)["ok"] is False

def test_wrong_owner_is_rejected():
    _,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); assert s.apply_account_access("r1","w2",a["token"],10)["ok"] is False

def test_approved_updates_value():
    repo,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); s.apply_account_access("r1","w1",a["token"],10); assert repo.get("r1").value == 10

def test_negative_value_denied():
    _,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); assert s.apply_account_access("r1","w1",a["token"],-1)["status"] == "denied"

def test_over_limit_review():
    _,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); assert s.apply_account_access("r1","w1",a["token"],150)["status"] == "review"

def test_blocked_metadata_denies():
    _,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); assert s.apply_account_access("r1","w1",a["token"],10,{"blocked": True})["status"] == "denied"

def test_review_reason_retained():
    _,_,_,s=setup_service(); a=s.acquire_account_access("r1","w1"); assert s.apply_account_access("r1","w1",a["token"],10,{"review": True})["reasons"] == ["review"]

def test_adapter_not_called_for_denied():
